local FontSize: GetTextBoundsParams = Instance.new("GetTextBoundsParams")
FontSize.Width = math.huge
local NotificationCache = {}
local NotificationList = {}
local Notifications
local GetVapeAsset
local VapeColors
local Components
local CreateSignal
local ClickGUI
local ScaledGUI
local BlurEffect
local BlurFocus
local BlurTween
local TopBarContainer: Instance?
local TopBarStats: Instance?
local TopBarHidden: boolean = false
local TopBarButtons: {[GuiObject]: boolean} = {}
