local Scale = {Scale = 1}
local BlurInfo: TweenInfo = TweenInfo.new(0.3, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
local GUI
local SortQueued: boolean = false
local BuildClock: number = os.clock()
local BuildBudget: number = 0.03

local function YieldBuild(Budget: number?)
    if os.clock() - BuildClock > (Budget or BuildBudget) then
        BuildBudget = math.clamp(task.wait(), 0.03, 0.07)
        BuildClock = os.clock()
    end
end

vape.YieldBuild = YieldBuild

local StagedWindows: {{Object: GuiObject?, Parent: Instance?, Build: (() -> ())?}} = {}
local WindowsMounted: boolean = false

local function StageWindow(Object: GuiObject, Parent: Instance)
    if WindowsMounted then
        Object.Parent = Parent
    else
        table.insert(StagedWindows, {Object = Object, Parent = Parent})
    end
end

local function StageBuild(Callback: () -> ())
    if WindowsMounted then
        Callback()
    else
        table.insert(StagedWindows, {Build = Callback})
    end
end

local function MountWindows(Budget: number?)
    local Started: number = os.clock()

    while StagedWindows[1] do
        local Entry = table.remove(StagedWindows, 1)
        if Entry.Build then
            local Success, Error = pcall(Entry.Build)
            if not Success then
                warn(`[blue inhaler] failed to build a staged window: {Error}`)
            end
        else
            pcall(function()
                Entry.Object.Parent = Entry.Parent
            end)
        end

        if Budget and os.clock() - Started > Budget then
            task.wait()
            Started = os.clock()
        end
    end

    WindowsMounted = true
end

local isfile = isfile or function(FilePath: string)
    local Success, Data = pcall(function()
        return readfile(FilePath)
    end)

    return Success and Data ~= nil and Data ~= ""
end

local function LoadJSON(FilePath: string)
    local Success, Data = pcall(function()
        return HttpService:JSONDecode(readfile(FilePath))
    end)

    return Success and type(Data) == "table" and Data or nil
end

local function WriteJSON(FilePath: string, Data)
    local Success, Encoded = pcall(HttpService.JSONEncode, HttpService, Data)
    if not Success then
        return false, Encoded
    end

    return pcall(writefile, FilePath, Encoded)
end

local NotificationsOff = isfile(`{vape.Directory}/profiles/notifications.txt`) and readfile(`{vape.Directory}/profiles/notifications.txt`) == "false"
local LoadFailures: number = 0
local DeferredLoads: number = 0
local LoadGeneration: number = 0
local LoadCalled: boolean = false
local CanSave: boolean = true
local NeedsSave: boolean = false
local function AttemptLoad(Object, Data, Name: string)
    local Success, Error = pcall(Object.Load, Object, Data)
    if not Success then
        LoadFailures += 1
        warn(`[blue inhaler] failed to load {Name}: {Error}`)
    end
end

local function FinishLoad()
    if not LoadCalled or DeferredLoads > 0 or vape.Loaded == nil then
        return
    end

    vape.Loaded = CanSave

    if SortQueued then
        vape:SortCategories(true)
    end

    if vape.Downloader then
        vape.Downloader:Destroy()
        vape.Downloader = nil
    end

    if NeedsSave then
        NeedsSave = false
        vape:Save()
    end

    if not WindowsMounted then
        task.spawn(function()
            if vape.ThreadFix then
                setthreadidentity(8)
            end

            task.wait()
            MountWindows(0.004)
        end)
    end
end

local FeatureTags
local function GetFeatureTag(Name: string)
    if not FeatureTags then
        FeatureTags = {}

        -- Feature tags are optional in the offline build.

local Features = LoadJSON(`{vape.Directory}/features.json`)
        for Tag: string, v: string in {updated = "updated", new = "added"} do
            local List = Features and Features[v]

            if type(List) == "table" then
                for _, Feature: any in List do
                    if type(Feature) == "string" then
                        FeatureTags[Feature] = Tag
                    end
                end
            end
        end
    end

    return FeatureTags[Name]
end

local Color = {}
local UIPallet = {}
do
    function Color.Dark(Color: Color3, Amount: number)
        local Hue, Sat, Val = Color:ToHSV()
        return Color3.fromHSV(Hue, Sat, math.clamp(select(3, UIPallet.Main:ToHSV()) > 0.5 and Val + Amount or Val - Amount, 0, 1))
    end

    function Color.Light(Color: Color3, Amount: number)
        local Hue, Sat, Val = Color:ToHSV()
        return Color3.fromHSV(Hue, Sat, math.clamp(select(3, UIPallet.Main:ToHSV()) > 0.5 and Val - Amount or Val + Amount, 0, 1))
    end

    function vape:Color(Hue: number)
        local Sat: number = 0.74 + (0.26 * math.min(Hue / 0.045, 1))

        if Hue > 0.577 then
            Sat = 1 - (0.48 * math.min((Hue - 0.577) / 0.088, 1))
        end

        if Hue > 0.674 then
            Sat = 0.52 + (0.48 * math.min((Hue - 0.674) / 0.149, 1))
        end

        if Hue > 0.869 then
            Sat = 1 - (0.26 * math.min((Hue - 0.869) / 0.131, 1))
        end

        return Hue, Sat, 1
    end

    function vape:TextColor(Hue: number, Sat: number, Val: number)
        if Val >= 0.7 and (Sat < 0.6 or Hue > 0.04 and Hue < 0.56) then
            return Color3.new(0.19, 0.19, 0.19)
        end

        return Color3.new(1, 1, 1)
    end
end

local function DeferredOption(Kind: string, Props, Children: Instance?, API, Order: number?, Constructor: ((...any) -> any)?)
    if Kind ~= "Toggle" and Kind ~= "Slider" and Kind ~= "Dropdown" and Kind ~= "TextList" and Kind ~= "ColorSlider" and Kind ~= "Targets" and Kind ~= "TwoSlider" and Kind ~= "TextBox" and (Kind ~= "Bind" or not Props.Module) then
        if not Constructor then
            return
        end

        local Before: number = #Children:GetChildren()
        local Result = Constructor(Props, Children, API)
        for i: number, Child: Instance in Children:GetChildren() do
            if i > Before and Child:IsA("GuiObject") then
                Child.LayoutOrder = Order or 0
            end
        end

        return Result
    end

    local Component = {Type = Kind, Index = 0}
    local Mounted
    local Callbacks = {}
    local BindColor: Color3?
    local Optional = {Bind = true, Name = true, Suffix = true, Mobile = true, Binding = true}
    local BindFunction = Props.Function
    Props.Function = Props.Function or function() end

    if Kind ~= "Bind" then
        for _ in API.Options do
            Component.Index += 1
        end
    end

    function Component:Color() end

    function Component:OnMount(Callback: () -> ())
        table.insert(Callbacks, Callback)
    end

    local function Mount()
        if Mounted then return Mounted end

        local Data = {}
        Component:Save(Data)
        local Settings = table.clone(Props)
        Settings.Function = function() end
        local Bind = rawget(Component, "Bind")
        local Triggered = rawget(Component, "Triggered")
        local Index: number = Component.Index
        local Minimum = rawget(Component, "Min")
        local Maximum = rawget(Component, "Max")
        local Before: number = Children and #Children:GetChildren() or 0
        Mounted = Components[Kind](Settings, Children, API)
        if Order and Children then
            for i: number, Child: Instance in Children:GetChildren() do
                if i > Before and Child:IsA("GuiObject") then
                    Child.LayoutOrder = Order
                end
            end
        end
        Mounted.Index = Index

        if Minimum then Mounted.Min = Minimum end
        if Maximum then Mounted.Max = Maximum end
        if Triggered then Mounted.Triggered = Triggered end
        Mounted:Load(Data[Kind == "Targets" and "Targets" or Props.Name or "Bind"])
        Settings.Function = Props.Function
        if BindColor then Mounted:SetColor(BindColor) end

        if Kind == "ColorSlider" then
            local Rainbow: number? = table.find(vape.RainbowSliders, Component)
            if Rainbow then table.remove(vape.RainbowSliders, Rainbow) end
        end

        if Kind == "Bind" then
            local Active: number? = table.find(vape.ActiveBinds, Component)
            if Active then table.remove(vape.ActiveBinds, Active) end
            if Props.Position then Mounted.Object.Position = Props.Position end
            API.Bind = Component
        else
            Mounted.Bind = Bind
            API.Options[Props.Name or Kind] = Component
        end

        table.clear(Component)
        setmetatable(Component, {
            __index = function(_, Key: string)
                if Key == "Mount" then return Mount end
                if Key == "OnMount" then return function(_, Callback) Callback() end end
                return Mounted[Key]
            end,
            __newindex = function(_, Key: string, Value)
                Mounted[Key] = Value
            end
        })

        if Kind ~= "Bind" and Mounted.Color then
            Mounted:Color(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value, vape.GUIColor.Rainbow and vape.RainbowMode.Value ~= "Retro")
        end
        for _, Callback: () -> () in Callbacks do Callback() end
        table.clear(Callbacks)

        return Mounted
    end

    if Kind == "Toggle" then
        Component.Default = Props.Default and true or false
        Component.Enabled = false
        Component.Name = Props.Name

        function Component:Toggle()
            self.Enabled = not self.Enabled
            vape:QueueSave()
            Props.Function(self.Enabled)
        end

        function Component:Load(Data)
            if self.Enabled ~= (Data.Enabled or false) then self:Toggle() end
            if self.Bind and Data.Bind then self.Bind:Load(Data.Bind) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {Enabled = self.Enabled}
            if self.Bind then self.Bind:Save(Data[Props.Name]) end
        end
    elseif Kind == "Slider" then
        Component.Decimal = Props.Decimal or 1
        Component.Default = Props.Default or Props.Min
        Component.Max = Props.Max
        Component.Min = Props.Min
        Component.Suffix = Props.Suffix
        Component.Value = Props.Default or Props.Min

        function Component:SetValue(Value: number, Position: number?, WasReleased: boolean?)
            if type(Value) ~= "number" or Value ~= Value or Value == math.huge or Value == -math.huge then return end
            if self.Value ~= Value or WasReleased then
                self.Value = Value
                vape:QueueSave()
                Props.Function(Value, WasReleased)
            end
        end

        function Component:Load(Data)
            local Value = Data.Value == Data.Max and Data.Max ~= self.Max and self.Max or Data.Value
            if type(Value) == "number" then Value = math.clamp(Value, self.Min, self.Max) end
            if self.Value ~= Value then self:SetValue(Value, nil, true) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {Value = self.Value, Max = self.Max}
        end
    elseif Kind == "Dropdown" then
        Component.Default = Props.Default or Props.List[1] or "None"
        Component.Index = 0
        Component.List = Props.List
        Component.Value = Props.List[1] or "None"

        function Component:SetValue(Value, IsClick: boolean?)
            self.Value = table.find(Props.List, Value) and Value or Props.List[1] or "None"
            vape:QueueSave()
            Props.Function(self.Value, IsClick)
        end

        function Component:Change(List: {string}?)
            Props.List = List or {}
            if not table.find(Props.List, self.Value) then self:SetValue(self.Value) end
        end

        function Component:Load(Data)
            if Data.Value and self.Value ~= Data.Value then self:SetValue(Data.Value) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {Value = self.Value}
        end
    elseif Kind == "TextList" then
        Component.Default = Props.Default and table.clone(Props.Default) or {}
        Component.List = Props.Default and table.clone(Props.Default) or {}
        Component.ListEnabled = Props.Default and table.clone(Props.Default) or {}
        Component.Icon = Props.Icon
        Optional.Icon = true

        function Component:ChangeValue(Value: string?)
            if Value then
                local Index: number? = table.find(self.List, Value)
                if Index then
                    table.remove(self.List, Index)
                    local Enabled: number? = table.find(self.ListEnabled, Value)
                    if Enabled then table.remove(self.ListEnabled, Enabled) end
                else
                    table.insert(self.List, Value)
                    table.insert(self.ListEnabled, Value)
                end
            end
            vape:QueueSave()
            Props.Function(self.List)
        end

        function Component:Load(Data)
            self.List = Data.List or {}
            self.ListEnabled = Data.ListEnabled or {}
            self:ChangeValue()
        end

        function Component:Save(Data)
            Data[Props.Name] = {List = self.List, ListEnabled = self.ListEnabled}
        end
    elseif Kind == "ColorSlider" then
        Component.Hue = Props.DefaultHue or 0.44
        Component.Sat = Props.DefaultSat or 1
        Component.Value = Props.DefaultValue or 1
        Component.Opacity = Props.DefaultOpacity or 1
        Component.Rainbow = false
        Component.Index = 0

        function Component:Toggle()
            self.Rainbow = not self.Rainbow
            if self.Rainbow then
                table.insert(vape.RainbowSliders, self)
            else
                local Index: number? = table.find(vape.RainbowSliders, self)
                if Index then table.remove(vape.RainbowSliders, Index) end
            end
            vape:QueueSave()
        end

        function Component:SetValue(Hue: number?, Sat: number?, Value: number?, Opacity: number?)
            self.Hue = Hue or self.Hue
            self.Sat = Sat or self.Sat
            self.Value = Value or self.Value
            self.Opacity = Opacity or self.Opacity
            if not self.Rainbow then vape:QueueSave() end
            Props.Function(self.Hue, self.Sat, self.Value, self.Opacity)
        end

        function Component:Load(Data)
            local Hue, Sat, Value, Opacity = Data.Hue or self.Hue, Data.Sat or self.Sat, Data.Value or self.Value, Data.Opacity or self.Opacity
            if (Data.Rainbow or false) ~= self.Rainbow then self:Toggle() end
            if self.Hue ~= Hue or self.Sat ~= Sat or self.Value ~= Value or self.Opacity ~= Opacity then self:SetValue(Hue, Sat, Value, Opacity) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {Hue = self.Hue, Sat = self.Sat, Value = self.Value, Opacity = self.Opacity, Rainbow = self.Rainbow}
        end
    elseif Kind == "Targets" then
        Component.Default = {
            Players = Props.Players and true or false,
            NPCs = Props.NPCs and true or false,
            Invisible = Props.Invisible and true or false,
            Walls = Props.Walls and true or false,
            Priority = "Players"
        }

        local function TargetButton(Enabled: boolean, Callback: (boolean?) -> ())
            local Button = {Enabled = Enabled, Type = "TargetsButton"}
            function Button:Toggle()
                self.Enabled = not self.Enabled
                vape:QueueSave()
                Callback(self.Enabled)
            end
            return Button
        end

        Component.Players = TargetButton(Component.Default.Players, function(Enabled) Props.Function(Enabled) end)
        Component.NPCs = TargetButton(Component.Default.NPCs, function(Enabled) Props.Function(Enabled) end)
        Component.Invisible = TargetButton(Component.Default.Invisible, function() Props.Function() end)
        Component.Walls = TargetButton(Component.Default.Walls, function() Props.Function() end)
        Component.Priority = {
            Default = "Players",
            List = {"Players", "NPCs", "None", "Closest", "Farthest", "Lowest health", "Highest health", "Crosshair"},
            Type = "Dropdown",
            Value = "Players"
        }

        function Component.Priority:SetValue(Value, IsClick: boolean?)
            self.Value = table.find(self.List, Value) and Value or self.List[1] or "None"
            vape:QueueSave()
            Props.Function(self.Value, IsClick)
        end

        function Component:Load(Data)
            if self.Players.Enabled ~= Data.Players then self.Players:Toggle() end
            if self.NPCs.Enabled ~= Data.NPCs then self.NPCs:Toggle() end
            if self.Invisible.Enabled ~= Data.Invisible then self.Invisible:Toggle() end
            if self.Walls.Enabled ~= Data.Walls then self.Walls:Toggle() end
            if Data.Priority and self.Priority.Value ~= Data.Priority then self.Priority:SetValue(Data.Priority) end
        end

        function Component:Save(Data)
            Data.Targets = {
                Players = self.Players.Enabled,
                NPCs = self.NPCs.Enabled,
                Invisible = self.Invisible.Enabled,
                Walls = self.Walls.Enabled,
                Priority = self.Priority.Value
            }
        end

        if Component.Players.Enabled then Props.Function(true) end
        if Component.NPCs.Enabled then Props.Function(true) end
        if Component.Invisible.Enabled then Props.Function() end
        if Component.Walls.Enabled then Props.Function() end
    elseif Kind == "TwoSlider" then
        Component.Decimal = Props.Decimal or 1
        Component.DefaultMin = Props.DefaultMin or Props.Min
        Component.DefaultMax = Props.DefaultMax or 10
        Component.Max = Props.Max
        Component.Min = Props.Min
        Component.ValueMin = Component.DefaultMin
        Component.ValueMax = Component.DefaultMax
        local RandomGenerator: Random = Random.new()

        function Component:GetRandomValue()
            return RandomGenerator:NextNumber(self.ValueMin, self.ValueMax)
        end

        function Component:SetValue(IsMax: boolean, Value: number)
            if type(Value) ~= "number" or Value ~= Value or Value == math.huge or Value == -math.huge then return end
            self[IsMax and "ValueMax" or "ValueMin"] = Value
            vape:QueueSave()
        end

        function Component:Load(Data)
            local ValueMin: number = Data.ValueMin or Data.Value or self.ValueMin
            local ValueMax: number = Data.ValueMax or Data.Value or self.ValueMax
            if self.ValueMin ~= ValueMin then self:SetValue(false, ValueMin) end
            if self.ValueMax ~= ValueMax then self:SetValue(true, ValueMax) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {ValueMin = self.ValueMin, ValueMax = self.ValueMax}
        end
    elseif Kind == "TextBox" then
        Component.Default = Props.Default or ""
        Component.Value = Component.Default

        function Component:SetValue(Value: string, Enter: boolean?)
            self.Value = Value
            vape:QueueSave()
            Props.Function(Enter)
        end

        function Component:Load(Data)
            if self.Value ~= Data.Value then self:SetValue(Data.Value) end
        end

        function Component:Save(Data)
            Data[Props.Name] = {Value = self.Value}
        end
    else
        Component.Hold = Props.Hold or false
        Component.Keys = {}
        Component.Triggered = CreateSignal()
        if BindFunction then
            Component.Triggered:Connect(BindFunction)
        end

        function Component:SetBind(Keys: {string}, Mouse: boolean?)
            if Mouse then return Mount():SetBind(Keys, Mouse) end
            self.Binding = nil
            self.Keys = table.clone(Keys)
            local Index: number? = table.find(vape.ActiveBinds, self)
            if #Keys == 0 and Index then
                table.remove(vape.ActiveBinds, Index)
            elseif #Keys > 0 and not Index then
                table.insert(vape.ActiveBinds, self)
            end
            vape:QueueSave()
        end

        function Component:SetVisible(Visible: boolean)
            if Visible or #self.Keys > 0 then Mount():SetVisible(Visible) end
        end

        function Component:SetColor(Color: Color3)
            BindColor = Color
        end

        function Component:Load(Data)
            if Data.Hold == nil then
                self.Hold = Props.Hold or false
            else
                self.Hold = Data.Hold
            end
            self:SetBind(Data.Keys)
            if Data.Mobile then Mount():Load(Data) end
        end

        function Component:Save(Data)
            Data[Props.Name or "Bind"] = {Keys = self.Keys, Hold = self.Hold}
        end

        function Component:Destroy()
            local Index: number? = table.find(vape.ActiveBinds, self)
            if Index then table.remove(vape.ActiveBinds, Index) end
            table.clear(self.Triggered.Connections)
        end
    end

    Component.Mount = Mount
    Component.Deferred = true
    setmetatable(Component, {
        __index = function(_, Key: string)
            if Optional[Key] then return end
            return Mount()[Key]
        end
    })

    if Kind == "Toggle" and Props.Default then Component:Toggle() end
    if Kind == "TextList" and Props.Default then Component:ChangeValue() end
    if Kind == "Bind" then
        API.Bind = Component
    else
        API.Options[Props.Name or Kind] = Component
    end

    return Component
end

local BoundsCache, OldCache = {}, {}
local BoundsCount: number = 0

local function GetFontBounds(Text: string, Size: number, FontFace, Width: number?)
    local Key = typeof(FontFace) == "Font" and `{Text}|{Size}|{Width or 0}|{FontFace.Family}|{FontFace.Weight.Name}|{FontFace.Style.Name}`
    if Key then
        local Cached: Vector2? = BoundsCache[Key] or OldCache[Key]
        if Cached then
            if not BoundsCache[Key] then
                BoundsCache[Key] = Cached
                BoundsCount += 1
            end
            return Cached
        end
    end

    FontSize.Text = Text
    FontSize.Size = Size
    FontSize.Width = Width or math.huge
    if typeof(FontFace) == "Font" then
        FontSize.Font = FontFace
    end

    local Bounds: Vector2 = TextService:GetTextBoundsAsync(FontSize)

    if Key then
        if BoundsCount > 2048 then
            OldCache, BoundsCache = BoundsCache, {}
            BoundsCount = 0
        end

        BoundsCache[Key] = Bounds
        BoundsCount += 1
    end

    return Bounds
end

