    local function CreateDownloader(Text: string)
        if vape.Loaded ~= true and vape.gui then
            local Downloader: TextLabel? = vape.Downloader
            if not Downloader then
                Downloader = Instance.new("TextLabel")
                Downloader.BackgroundTransparency = 1
                Downloader.FontFace = UIPallet.Font
                Downloader.Size = UDim2.new(1, 0, 0, 40)
                Downloader.TextColor3 = Color3.new(1, 1, 1)
                Downloader.TextSize = 20
                Downloader.TextStrokeTransparency = 0
                if vape.ThreadFix then
                    setthreadidentity(8)
                end
                Downloader.Parent = vape.gui
                vape.Downloader = Downloader
            end

            Downloader.Text = `Downloading {Text}`
        end
    end

    local AssetFolder: string = `{vape.Directory}/assets/new/`
    local AssetFiles: {[string]: boolean}?

    local function AssetExists(FilePath: string): boolean
        if FilePath:sub(1, #AssetFolder) ~= AssetFolder then
            return isfile(FilePath)
        end

        if not AssetFiles then
            AssetFiles = {}

            local Success, Files = pcall(listfiles, AssetFolder:sub(1, -2))
            for _, v: string in Success and Files or {} do
                local Name: string? = v:match("([^/\\]+)$")
                if Name then
                    AssetFiles[Name] = true
                end
            end
        end

        return AssetFiles[FilePath:sub(#AssetFolder + 1)] or isfile(FilePath)
    end

    local function DownloadFile(FilePath: string, Callback: ((string) -> any)?)
        if not AssetExists(FilePath) then
            if FilePath:sub(1, #AssetFolder) == AssetFolder then
                -- Use embedded fallback artwork when optional local assets are absent.
                return Callback and Callback() or ""
            end
            error(`Blue Inhaler offline dependency missing: ${FilePath}`)
        end
        return (Callback or readfile)(FilePath)
    end

    local AssetCache, AssetFailed = {}

    GetVapeAsset = getcustomasset and function(FilePath: string)
        local Asset: string? = AssetCache[FilePath]

        if Asset == nil then
            Asset = DownloadFile(FilePath, function()
                local Success, Result = pcall(getcustomasset, FilePath)
                if Success then
                    return Result
                end

                if not AssetFailed then
                    AssetFailed = true
                    task.spawn(function()
                        repeat task.wait() until vape.Loaded ~= false
                        if vape.Loaded then
                            vape:CreateNotification("Blue Inhaler", `Your executor could not load custom assets, so icons and fonts use backups ({Result})`, 15, "warning")
                        end
                    end)
                end
                return VapeAssets[FilePath] or ""
            end)
            AssetCache[FilePath] = Asset
        end

        return Asset
    end or function(FilePath: string)
        return VapeAssets[FilePath] or ""
    end
end

local HexColor = {}

function HexColor.Format(Value: Color3): string
    return string.format("#%02X%02X%02X", math.round(Value.R * 255), math.round(Value.G * 255), math.round(Value.B * 255))
end

function HexColor.Parse(Text: string): Color3?
    local Parts: {string} = Text:split(",")
    if #Parts == 3 then
        local Red, Green, Blue = tonumber(Parts[1]), tonumber(Parts[2]), tonumber(Parts[3])
        if Red and Green and Blue then
            return Color3.fromRGB(math.clamp(Red, 0, 255), math.clamp(Green, 0, 255), math.clamp(Blue, 0, 255))
        end

        return nil
    end

    local Hex: string = (Text:gsub("[%s#]", "")):lower()
    if #Hex == 3 then
        Hex = Hex:gsub(".", "%0%0")
    end

    if #Hex == 6 and not Hex:find("%X") then
        return Color3.fromHex(Hex)
    end

    return nil
end

local Tween = setmetatable({}, {
    __index = function()
        return {}
    end
})

do
    function Tween:Tween(Object: Instance, Info: TweenInfo, Goal: {[string]: any}, Index)
        Index = self[Index or "tweens"]
        if Index[Object] then
            Index[Object]:Cancel()
            Index[Object] = nil
        end

        if vape.Loaded and Object.Parent and (Object:IsA("UIStroke") or Object.Visible) then
            Index[Object] = TweenService:Create(Object, Info, Goal)
            Index[Object].Completed:Once(function()
                if Index then
                    Index[Object] = nil
                    Index = nil
                end
            end)

            Index[Object]:Play()
        else
            for Property: string, Value: any in Goal do
                Object[Property] = Value
            end
        end
    end

    function Tween:Cancel(Object: Instance, Index)
        Index = self[Index or "tweens"]

        if Index[Object] then
            Index[Object]:Cancel()
            Index[Object] = nil
        end
    end
end


UIPallet = {
    Main = Color3.fromRGB(26, 25, 26),
    Text = Color3.fromRGB(200, 200, 200),
    Font = Font.fromEnum(Enum.Font.Arial),
    FontSemiBold = Font.fromEnum(Enum.Font.Arial, Enum.FontWeight.SemiBold),
    FontBold = Font.fromEnum(Enum.Font.Arial, Enum.FontWeight.Bold),
    FontDisplay = Font.new(Font.fromEnum(Enum.Font.Roboto).Family, Enum.FontWeight.Medium),
    DisplayScale = 0.845,
    Tween = TweenInfo.new(0.16, Enum.EasingStyle.Linear)
}

do
    local Success, Family = pcall(function()
        local Regular: string = GetVapeAsset(`{vape.Directory}/assets/new/proxima.ttf`)
        local Bold: string = GetVapeAsset(`{vape.Directory}/assets/new/proximabd.ttf`)
        if Regular == "" or Bold == "" then return end

        writefile(`{vape.Directory}/assets/new/proxima.json`, HttpService:JSONEncode({
            name = "Proxima",
            faces = {
                {name = "Regular", weight = 400, style = "normal", assetId = Regular},
                {name = "SemiBold", weight = 600, style = "normal", assetId = Bold},
                {name = "Bold", weight = 700, style = "normal", assetId = Bold}
            }
        }))

        return getcustomasset(`{vape.Directory}/assets/new/proxima.json`)
    end)

    if Success and Family and Family ~= "" then
        UIPallet.Font = Font.new(Family, Enum.FontWeight.Regular)
    end

    local DisplaySuccess, DisplayFamily = pcall(function()
        local Regular: string = GetVapeAsset(`{vape.Directory}/assets/new/bahnschrift.ttf`)
        if Regular == "" then return end

        writefile(`{vape.Directory}/assets/new/bahnschrift.json`, HttpService:JSONEncode({
            name = "Bahnschrift",
            faces = {
                {name = "Regular", weight = 400, style = "normal", assetId = Regular}
            }
        }))

        return getcustomasset(`{vape.Directory}/assets/new/bahnschrift.json`)
    end)

    if DisplaySuccess and DisplayFamily and DisplayFamily ~= "" then
        UIPallet.FontDisplay = Font.new(DisplayFamily, Enum.FontWeight.Regular)
        UIPallet.DisplayScale = 0.845
    else
        UIPallet.DisplayScale = 1
    end

    local Data = isfile(`{vape.Directory}/profiles/color.txt`) and LoadJSON(`{vape.Directory}/profiles/color.txt`)
    if Data then
        UIPallet.Main = Data.Main and Color3.fromRGB(unpack(Data.Main)) or UIPallet.Main
        UIPallet.Text = Data.Text and Color3.fromRGB(unpack(Data.Text)) or UIPallet.Text
        UIPallet.Font = Data.Font and Font.new(
            Data.Font:find("rbxasset") and Data.Font
            or string.format("rbxasset://fonts/families/%s.json", Data.Font)
        ) or UIPallet.Font
    end

    UIPallet.FontSemiBold = Font.new(UIPallet.Font.Family, Enum.FontWeight.SemiBold)
    UIPallet.FontBold = Font.new(UIPallet.Font.Family, Enum.FontWeight.Bold)
    FontSize.Font = UIPallet.Font
end

