	                    AddOptionBinds(Module)
	                end
	            end
	        else
	            for _, Container: any in {vape.Modules, vape.Legit.Modules} do
	                for _, Module: any in Container do
	                    for _, Component: any in Module.Options do
	                        if Component.Bind then
	                            Component.Bind:Destroy()
	                            Component.Bind = nil
	                        end
	                    end
	                end
	            end
	
