	                table.insert(Categories, Category)
	            end
	        end
	
	        table.sort(Categories, function(A, B)
	            return (Priority[A.Object.Name] or 99) < (Priority[B.Object.Name] or 99)
	        end)
	
	        local Index: number = 0
