		            Hovered = true
		            Paint()
		
		            Tween:Tween(Button, UIPallet.Tween, {
		                BackgroundTransparency = 0
		            })
		        end)
		        Button.MouseLeave:Connect(function()
		            Hovered = false
		            Paint()
		
		            Tween:Tween(Button, UIPallet.Tween, {
		                BackgroundTransparency = 1
		            })
		        end)
		
