		    local function AddValueRow(Entry, Order: number, Text: string)
		        local Row: Frame = Instance.new("Frame")
		        Row.BackgroundTransparency = 1
		        Row.LayoutOrder = Order
		        Row.Name = Entry.Name
		        Row.Size = UDim2.new(1, 0, 0, 30)
