		        if Button.Enabled then
		            Button.Object.TextColor3 = IsRainbow and Color3.fromHSV(vape:Color((Hue - (Button.Index * 0.025)) % 1)) or Color3.fromHSV(Hue, Sat, Val)
		
		            if Button.Icon then
