		    Enabled = false,
		    Favorited = false,
		    Legit = true,
		    Name = Props.Name,
		    Options = {},
		    Tooltip = Props.Tooltip,
		    Type = "LegitModule"
		}
		local Dashes: {Frame} = {}
		local DashHolder: Frame?
