		        Component.Group = TabName
		
		        for Name: string, Button: TextButton in Component.Tabs do
		            Button.TextColor3 = Name == TabName and Color3.new(1, 1, 1) or VapeColors.Secondary
		            Button.Underline.Visible = Name == TabName
		        end
		
		        Component:Refresh()
		    end)
