		    Props.Tags[i] = Tag:lower()
		    Component.Paid = Component.Paid or Tag == "PAID"
		    local Indicator: TextLabel = Instance.new("TextLabel")
		    Indicator.BackgroundColor3 = Color3.new(1, 1, 1)
