		    self.HUD = Gui
		    local function CanEdit(): boolean
		        if vape.ThreadFix then setthreadidentity(8) end
		        return ClickGUI.Visible or vape.Legit.Window.Visible
		    end
		    AddDragHandler(Gui, CanEdit)
		
		    if self.HUDPosition then
		        Gui.Position = UDim2.fromOffset(self.HUDPosition.X, self.HUDPosition.Y)
		    end
		
		    HUDStroke = Instance.new("UIStroke")
		    HUDStroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
		    HUDStroke.Color = VapeColors.AccentHover
		    HUDStroke.Thickness = 0
