		    rated = function(A, B)
		        if (A.likes or 0) == (B.likes or 0) then
		            return A.Uploaded > B.Uploaded
		        end
		
		        return (A.likes or 0) > (B.likes or 0)
		    end,
		    downloaded = function(A, B)
		        if (A.downloads or 0) == (B.downloads or 0) then
		            return A.Uploaded > B.Uploaded
		        end
		
		        return (A.downloads or 0) > (B.downloads or 0)
