		        })
		
		        Tween:Tween(Icon, UIPallet.Tween, {
		            ImageColor3 = Color.Light(UIPallet.Main, 0.37)
		        })
		    end
		end)
		
		TargetsButton.MouseButton1Click:Connect(function()
		    Component:Toggle()
		end)
		
		return Component
